16	/// On success, writes the entry through to the `entries` Hive box (`Box
17	/// <Map>`, keyed by id, raw `EntryDto.toJson()` — Design Notes) *before*
18	/// returning `right(...)`, same "persist then return" ordering
19	/// `AuthRepositoryImpl._authenticate` already uses for its own
20	/// post-success side effect.
21	class EntriesRepositoryImpl implements EntriesRepository {
22	  EntriesRepositoryImpl({
23	    required EntriesRemoteDataSource remoteDataSource,
24	    required Box<Map> entriesBox,
25	  }) : _remoteDataSource = remoteDataSource,
26	       _entriesBox = entriesBox;
27	
28	  final EntriesRemoteDataSource _remoteDataSource;
29	  final Box<Map> _entriesBox;
30	
31	  @override
32	  Future<Either<Failure, Entry>> create({
33	    required String content,
34	    required EntrySource source,
35	    int? mediaDurationSeconds,
36	  }) async {
37	    final result = await _remoteDataSource.create(
38	      content: content,
39	      source: source,
40	      mediaDurationSeconds: mediaDurationSeconds,
41	    );
42	    return result.match((failure) async => left(failure), (dto) async {
43	      // A thrown Hive/disk exception must never escape unmapped (RNF09) —
44	      // same rationale/fallback `AuthRepositoryImpl` already uses for its
45	      // own local-persistence step.
46	      try {
47	        await _entriesBox.put(dto.id, dto.toJson());
48	      } catch (error) {
49	        return left(Failure.malformedResponse(message: error.toString()));
50	      }
51	      return right(_toEntry(dto));
52	    });
53	  }
54	
55	  @override
56	  Future<Either<Failure, EntriesPage>> list({
57	    String? cursor,
58	    int limit = 20,
59	    EntrySource? source,
60	    DateTime? dateFrom,
61	    DateTime? dateTo,
62	  }) async {
63	    final result = await _remoteDataSource.list(
64	      cursor: cursor,
65	      limit: limit,
66	      source: source,
67	      dateFrom: dateFrom,
68	      dateTo: dateTo,
69	    );
70	    return result.match(
71	      (failure) async {
72	        // Boundaries/Design Notes: the Hive-cache fallback is scoped to
73	        // `cursor == null` (the first/fresh page) only — a paginated
74	        // continuation (`cursor != null`) that fails with
75	        // `networkOffline`/`networkTimeout` propagates as `Left` like any
76	        // other pagination failure instead, so `MeusRegistrosCubit`'s own
77	        // `loadMoreFailed`/retry path handles it uniformly rather than a
78	        // full unrelated cache dump silently replacing the in-progress
79	        // paginated list (and breaking its newest-first ordering).
80	        if (cursor == null &&
81	            (failure is NetworkOffline || failure is NetworkTimeout)) {
82	          return _offlineFallback();
83	        }
84	        return left(failure);
85	      },
86	      (page) async {
87	        try {
88	          await _entriesBox.putAll({
89	            for (final dto in page.items) dto.id: dto.toJson(),
90	          });
91	        } catch (error) {
92	          // Same RNF09 rationale as `create()`'s own Hive-write guard — a
93	          // thrown Hive/disk exception must never escape unmapped.
94	          return left(Failure.malformedResponse(message: error.toString()));
95	        }
96	        return right(
97	          EntriesPage(
98	            items: page.items.map(_toEntry).toList(),
99	            nextCursor: page.nextCursor,
100	          ),
101	        );
102	      },
103	    );
104	  }
105	
106	  @override
107	  Future<Either<Failure, Entry>> getById(String id) async {
108	    final result = await _remoteDataSource.get(id);
109	    return result.match(
110	      (failure) async {
111	        // Boundaries: scoped to networkOffline/networkTimeout specifically
112	        // — every other Failure (notFound included) propagates as Left,
113	        // unmapped, same convention `list()`'s own cursor-scoped fallback
114	        // above uses.
115	        if (failure is NetworkOffline || failure is NetworkTimeout) {
116	          return _cachedEntryOrOriginalFailure(id, failure);
117	        }
118	        return left(failure);
119	      },
120	      (dto) async {
121	        // Same RNF09 rationale as `create()`/`list()`'s own Hive-write
122	        // guards — a thrown Hive/disk exception must never escape
123	        // unmapped.
124	        try {
125	          await _entriesBox.put(dto.id, dto.toJson());
126	        } catch (error) {
127	          return left(Failure.malformedResponse(message: error.toString()));
128	        }
129	        return right(_toEntry(dto));
130	      },
131	    );
132	  }
133	
134	  @override
135	  Future<Either<Failure, List<Entry>>> search(String query) async {
136	    final result = await _remoteDataSource.search(query);
137	    return result.match(
138	      (failure) async {
139	        // Boundaries/AD-9: no cache fallback for search, unlike
140	        // list()/getById() — every Failure (including
141	        // networkOffline/networkTimeout) propagates as Left, unmapped.
142	        return left(failure);
143	      },
144	      (dtos) async {
145	        // Review finding: de-duplicated by id first (first-occurrence-wins,
146	        // same semantics as `MeusRegistrosCubit`'s own trust-but-verify
147	        // convention for server data, shared via `core/utils/
148	        // deduped_by_id.dart`) — so the `putAll` below and the returned
149	        // list stay consistent, and `_SearchResults`' `ListView.builder`
150	        // (keyed by `ValueKey(entry.id)`) never sees a duplicate key even
151	        // if the backend ever violated its own no-duplicate-ids invariant.
152	        final dedupedDtos = dedupedById(dtos, (dto) => dto.id);
153	        // Same RNF09 rationale as create()/list()/getById()'s own
154	        // Hive-write guards — a thrown Hive/disk exception must never
155	        // escape unmapped.
156	        try {
157	          await _entriesBox.putAll({
158	            for (final dto in dedupedDtos) dto.id: dto.toJson(),
159	          });
160	        } catch (error) {
161	          return left(Failure.malformedResponse(message: error.toString()));
162	        }
163	        return right(dedupedDtos.map(_toEntry).toList());
164	      },
165	    );
166	  }
167	
168	  /// [getById]'s own offline/timeout fallback (Boundaries): a cache hit
169	  /// returns `Right` from the cached `EntryDto`; a cache miss propagates
170	  /// [originalFailure] unchanged — "no synthesized not-found" — rather than
171	  /// inventing a [Failure.notFound] this repository never actually
172	  /// received from the backend. A corrupt cached entry (should never
173	  /// happen — every entry here was written by [create]/[list]/[getById]
174	  /// themselves) maps to `Left(malformedResponse)` rather than throwing
175	  /// (RNF09), same guard `_offlineFallback()`'s own malformed-cache check
176	  /// uses.
177	  Either<Failure, Entry> _cachedEntryOrOriginalFailure(
178	    String id,
179	    Failure originalFailure,
180	  ) {
181	    try {
182	      final cached = _entriesBox.get(id);
183	      if (cached == null) {
184	        return left(originalFailure);
185	      }
186	      return right(
187	        _toEntry(EntryDto.fromJson(Map<String, dynamic>.from(cached))),
188	      );
189	    } catch (error) {
190	      return left(Failure.malformedResponse(message: error.toString()));
191	    }
192	  }
193	
194	  /// The offline/timeout fallback (Boundaries): a full `entries` Hive box
195	  /// dump, sorted `occurredAt` desc, always `nextCursor: null` — a cached
196	  /// dump has no further page to request. A corrupt cached entry (should
197	  /// never happen — every entry here was written by [create]/[list]
198	  /// themselves) maps to `Left(malformedResponse)` rather than throwing
199	  /// (RNF09), same guard `create()`'s own Hive write already has.
200	  Either<Failure, EntriesPage> _offlineFallback() {
201	    try {
202	      final entries =
203	          _entriesBox.values
204	              .map(
205	                (json) => _toEntry(
206	                  EntryDto.fromJson(Map<String, dynamic>.from(json)),
207	                ),
208	              )
209	              .toList()
210	            ..sort(
211	              (a, b) =>
212	                  DateTime.parse(b.occurredAt)
213	                      .compareTo(DateTime.parse(a.occurredAt)),
214	            );
215	      return right(EntriesPage(items: entries, nextCursor: null));
216	    } catch (error) {
217	      return left(Failure.malformedResponse(message: error.toString()));
218	    }
219	  }
220	
221	  Entry _toEntry(EntryDto dto) => Entry(
222	    id: dto.id,
223	    content: dto.content,
224	    source: dto.source,
225	    chatMessageId: dto.chatMessageId,
226	    occurredAt: dto.occurredAt,
227	    serverRevision: dto.serverRevision,
228	    createdAt: dto.createdAt,
229	    updatedAt: dto.updatedAt,
230	    mediaDurationSeconds: dto.mediaDurationSeconds,
231	  );
232	}
