12	/// Drives `MeusRegistrosScreen` — calls `EntriesRepository.list()` directly
13	/// (no use-case layer, matching this codebase's existing small-scope
14	/// convention: `AccountSettingsCubit`/`AuthCubit`/`TextEntryCubit`). A
15	/// `lazySingleton` (Code Map), like `AccountSettingsCubit` — long-lived, so
16	/// the already-fetched pages survive leaving and re-entering
17	/// `/meus-registros` within the same app session.
18	///
19	/// spec-4-2 — also subscribes to [PendingEntryWriteTracker.pendingWrites]/
20	/// `.confirmedWrites` for this cubit's whole lifetime (constructor-wired,
21	/// not `loadFirstPage()`-wired): both streams are shared singleton
22	/// broadcasts a capture cubit on a *different* screen can drive at any
23	/// time, and this cubit is itself a long-lived singleton that must reflect
24	/// them regardless of which screen is currently visible.
25	class MeusRegistrosCubit extends Cubit<MeusRegistrosState> {
26	  MeusRegistrosCubit(this._repository, this._tracker)
27	    : super(const MeusRegistrosLoading()) {
28	    _pendingSubscription = _tracker.pendingWrites.listen(
29	      _onPendingWritesChanged,
30	    );
31	    _confirmedSubscription = _tracker.confirmedWrites.listen(_onEntryConfirmed);
32	  }
33	
34	  final EntriesRepository _repository;
35	  final PendingEntryWriteTracker _tracker;
36	  late final StreamSubscription<List<PendingEntryWrite>> _pendingSubscription;
37	  late final StreamSubscription<({String tempId, Entry entry})>
38	  _confirmedSubscription;
39	
40	  /// Mirrors the tracker's own latest snapshot regardless of [state]'s
41	  /// current type — so a pending write that arrives while [state] is
42	  /// still [MeusRegistrosLoading]/[MeusRegistrosError] isn't lost: the
43	  /// next [loadFirstPage] that resolves into [MeusRegistrosLoaded]/
44	  /// [MeusRegistrosEmpty] seeds itself from this field directly.
45	  List<PendingEntryWrite> _pendingWrites = const [];
46	
47	  /// A monotonic counter guarding against a stale in-flight call's result
48	  /// landing after a newer call has already changed the state (e.g. the
49	  /// user leaves and quickly re-enters `/meus-registros` while a slow
50	  /// first request is still pending, or taps retry before the original
51	  /// request resolves). Incremented at the start of every [loadFirstPage],
52	  /// then captured locally before each `await` in [loadFirstPage]/
53	  /// [_fetchMore] — a result whose captured generation no longer matches
54	  /// this counter by the time it resolves is discarded rather than
55	  /// emitted.
56	  int _generation = 0;
57	
58	  /// spec-5-2 — the session-scoped filter selection (Design Notes): `null`
59	  /// for each field means "no filter of that kind", never a sentinel
60	  /// value. Reset to "no filters" by [loadFirstPage] itself (a fresh
61	  /// mount always starts from the full unfiltered timeline — same
62	  /// "always re-fetches from scratch" contract that method's own doc
63	  /// already gives, extended here to the filter selection too), set by
64	  /// [applyFilters], cleared by [clearFilters], and carried forward by
65	  /// every [_fetchMore] call so a paginated continuation never silently
66	  /// drops the filters its first page was fetched with.
67	  EntrySource? _activeSource;
68	  DateTime? _activeDateFrom;
69	  DateTime? _activeDateTo;
70	
71	  /// `MeusRegistrosScreen`'s own read of the current filter selection —
72	  /// deliberately not part of [MeusRegistrosState] itself: [applyFilters]/
73	  /// [clearFilters] already re-emit a new state on every change, so
74	  /// whichever `BlocBuilder` reads these getters during its own `builder`
75	  /// callback rebuilds in lockstep with them regardless.
76	  EntrySource? get activeSource => _activeSource;
77	  DateTime? get activeDateFrom => _activeDateFrom;
78	  DateTime? get activeDateTo => _activeDateTo;
79	
80	  /// `EntriesSearchBar.hasActiveFilters`/the active-filter chip row's own
81	  /// "is any filter active at all" check.
82	  bool get hasActiveFilters =>
83	      _activeSource != null || _activeDateFrom != null || _activeDateTo != null;
84	
85	  void _onPendingWritesChanged(List<PendingEntryWrite> pendingWrites) {
86	    _pendingWrites = pendingWrites;
87	    final current = state;
88	    if (current is MeusRegistrosLoaded) {
89	      emit(current.copyWith(pendingWrites: pendingWrites));
90	    } else if ((current is MeusRegistrosEmpty ||
91	            current is MeusRegistrosError) &&
92	        pendingWrites.isNotEmpty) {
93	      // A capture save starts while this screen is showing "no entries
94	      // yet" or a load failure (Review finding: the latter previously
95	      // fell through this check entirely, silently dropping the pending
96	      // card) — its own placeholder card must still show immediately
97	      // (Acceptance Criteria), not wait for a reload.
98	      emit(
99	        MeusRegistrosLoaded(
100	          entries: const [],
101	          nextCursor: null,
102	          pendingWrites: pendingWrites,
103	        ),
104	      );
105	    }
106	    // MeusRegistrosLoading: nothing to overlay onto yet — [_pendingWrites]
107	    // above already keeps the latest snapshot, which the next
108	    // loadFirstPage() resolution reads directly.
109	  }
110	
111	  void _onEntryConfirmed(({String tempId, Entry entry}) confirmation) {
112	    final entry = confirmation.entry;
113	    // Review finding: drops this write's own pending placeholder from
114	    // this cubit's *local* record synchronously with prepending the
115	    // confirmed entry, in the very same handler — the tracker's own
116	    // `pendingWrites` stream will also eventually deliver the matching
117	    // removal, but that's a separate `Stream.multi`-wrapped subscription
118	    // that can land one microtask late, which previously left a one-frame
119	    // window where both the stale placeholder and the real confirmed
120	    // entry rendered at once.
121	    _pendingWrites = [
122	      for (final pending in _pendingWrites)
123	        if (pending.tempId != confirmation.tempId) pending,
124	    ];
125	    final current = state;
126	    if (current is MeusRegistrosLoaded) {
127	      // Prepended, not reloaded (Design Notes) — preserves this cubit's
128	      // own pagination state (`nextCursor`/`loadMoreFailed`) exactly as
129	      // `loadMore()`'s own cursor-overlap robustness already relies on;
130	      // `dedupedById` (unchanged) absorbs the degenerate case where a
131	      // later `list()`/`loadMore()` page's cursor also happens to repeat
132	      // this same (now server-known) id.
133	      emit(
134	        current.copyWith(
135	          entries: dedupedById([entry, ...current.entries], (e) => e.id),
136	          pendingWrites: _pendingWrites,
137	        ),
138	      );
139	    } else if (current is MeusRegistrosEmpty || current is MeusRegistrosError) {
140	      // Review finding: MeusRegistrosError previously fell through this
141	      // check too, same rationale as `_onPendingWritesChanged` above.
142	      emit(
143	        MeusRegistrosLoaded(
144	          entries: [entry],
145	          nextCursor: null,
146	          pendingWrites: _pendingWrites,
147	        ),
148	      );
149	    }
150	    // MeusRegistrosLoading: the next loadFirstPage() fetches the server's
151	    // own fresh page, which already includes this entry now that it's
152	    // confirmed server-side — nothing to reconcile.
153	  }
154	
155	  /// `EntryRecordCard`'s own retry tap (`MeusRegistrosScreen`) — forwards
156	  /// to the shared tracker verbatim (Never: "a second retry endpoint").
157	  Future<void> retry(String tempId) => _tracker.retry(tempId);
158	
159	  /// `MeusRegistrosScreen.initState` calls this once, every mount — always
160	  /// re-fetches from scratch rather than keeping a previous visit's page
161	  /// around, since a new entry may have been saved (Insertion Modal, Epic
162	  /// 3) since the last visit. spec-5-2: also resets the filter selection
163	  /// to "none" first (a fresh mount's own "from scratch" promise extended
164	  /// to filters, Design Notes) — [_loadFiltered] then runs with that
165	  /// cleared selection, same as [clearFilters] would.
166	  Future<void> loadFirstPage() {
167	    _activeSource = null;
168	    _activeDateFrom = null;
169	    _activeDateTo = null;
170	    return _loadFiltered();
171	  }
172	
173	  /// `EntriesFilterSheet`'s own "Aplicar" button (spec-5-2) — replaces
174	  /// whichever filters were active before with exactly [source]/
175	  /// [dateFrom]/[dateTo] (never merged with the previous selection: the
176	  /// active-filter chip row's own "x" already recomputes the full
177	  /// replacement set itself, passing back in every filter it wants kept —
178	  /// I/O matrix: "Remove one of two active chips"). Omitting a parameter
179	  /// clears that one filter dimension; omitting all three is equivalent to
180	  /// [clearFilters]. A separate method from [loadFirstPage] by design —
181	  /// see Design Notes — though both ultimately share [_loadFiltered]'s own
182	  /// "bump generation, replace state via list()" body.
183	  Future<void> applyFilters({
184	    EntrySource? source,
185	    DateTime? dateFrom,
186	    DateTime? dateTo,
187	  }) {
188	    _activeSource = source;
189	    _activeDateFrom = dateFrom;
190	    _activeDateTo = dateTo;
191	    return _loadFiltered();
192	  }
193	
194	  /// The active-filter chip row's own "Limpar filtros" link (spec-5-2) —
195	  /// restores the full unfiltered list in place (I/O matrix: "Clear all
196	  /// filters"), without a screen reload/re-mount.
197	  Future<void> clearFilters() {
198	    _activeSource = null;
199	    _activeDateFrom = null;
200	    _activeDateTo = null;
201	    return _loadFiltered();
202	  }
203	
204	  /// [loadFirstPage]/[applyFilters]/[clearFilters]'s own shared "bump
205	  /// generation, replace state via list()" body — always queries
206	  /// whichever filter selection ([_activeSource]/[_activeDateFrom]/
207	  /// [_activeDateTo]) is current at call time, cursor-less (always a
208	  /// fresh first page, never a continuation — [_fetchMore] is the one
209	  /// path that ever passes a cursor).
210	  Future<void> _loadFiltered() async {
211	    final generation = ++_generation;
212	    emit(const MeusRegistrosLoading());
213	    final result = await _repository.list(
214	      source: _activeSource,
215	      dateFrom: _activeDateFrom,
216	      dateTo: _activeDateTo,
217	    );
218	    // Mirrors `AccountSettingsCubit.toggleBiometric`'s own guard: `close()`
219	    // can race this awaited call (e.g. a fast app teardown mid-request) —
220	    // `emit()` after `close()` would otherwise throw.
221	    if (isClosed || generation != _generation) {
222	      return;
223	    }
224	    result.match(
225	      (failure) {
226	        // Review finding (round 2): mirrors the success branch's own
227	        // `_pendingWrites` overlay below — a write already pending/failed
228	        // when the first page fails to load must still show its own
229	        // placeholder card, not disappear behind a plain error screen
230	        // until the next unrelated `pendingWrites` emission.
231	        if (_pendingWrites.isEmpty) {
232	          emit(MeusRegistrosError(message: failure.message));
233	          return;
234	        }
235	        emit(
236	          MeusRegistrosLoaded(
237	            entries: const [],
238	            nextCursor: null,
239	            pendingWrites: _pendingWrites,
240	          ),
241	        );
242	      },
243	      (page) {
244	        // Same degenerate-cursor distrust as `_fetchMore`'s own guard below:
245	        // a page reporting zero items is treated as exhausted regardless of
246	        // `page.nextCursor` — an empty first page with a non-null cursor
247	        // would otherwise strand the user on `MeusRegistrosEmpty` with no
248	        // way back to a cursor this state no longer tracks. Forced
249	        // unconditionally (Review finding, round 1): independent of
250	        // `_pendingWrites` below — a pending write outstanding over an
251	        // otherwise-empty first page must still null out the cursor, not
252	        // just skip the `MeusRegistrosEmpty` branch beneath it.
253	        final nextCursor = page.items.isEmpty ? null : page.nextCursor;
254	        // spec-4-2: a pending write already outstanding still needs its
255	        // own placeholder card to show, even over an otherwise-empty first
256	        // page — skips straight to `MeusRegistrosEmpty` only once neither
257	        // applies.
258	        if (page.items.isEmpty && _pendingWrites.isEmpty) {
259	          emit(const MeusRegistrosEmpty());
260	          return;
261	        }
262	        emit(
263	          MeusRegistrosLoaded(
264	            entries: dedupedById(page.items, (entry) => entry.id),
265	            nextCursor: nextCursor,
266	            pendingWrites: _pendingWrites,
267	          ),
268	        );
269	      },
270	    );
271	  }
272	
273	  /// `MeusRegistrosScreen`'s scroll listener calls this near the list's
274	  /// end. A no-op while not [MeusRegistrosLoaded], while
275	  /// [MeusRegistrosLoaded.nextCursor] is already `null`, while a call is
276	  /// already in flight, or — critically — once
277	  /// [MeusRegistrosLoaded.loadMoreFailed] is already `true`: without that
278	  /// last guard, a failed page's own footer swapping from a spinner to a
279	  /// "Tentar novamente" button can shift the list's `maxScrollExtent`
280	  /// just enough to leave the scroll position still inside the
281	  /// pre-fetch-buffer zone, re-firing this same listener and retrying
282	  /// forever — observed directly as an unbounded `pumpAndSettle` loop in
283	  /// this screen's own widget test. Once failed, only an explicit
284	  /// [retryLoadMore] (the footer's own button) tries again.
285	  Future<void> loadMore() => _fetchMore(isRetry: false);
286	
287	  /// The footer's "Tentar novamente" button — the one path allowed to
288	  /// retry past a [MeusRegistrosLoaded.loadMoreFailed] of `true`
289	  /// ([loadMore]'s own doc).
290	  Future<void> retryLoadMore() => _fetchMore(isRetry: true);
291	
292	  Future<void> _fetchMore({required bool isRetry}) async {
293	    final current = state;
294	    if (current is! MeusRegistrosLoaded ||
295	        current.nextCursor == null ||
296	        current.isLoadingMore ||
297	        (current.loadMoreFailed && !isRetry)) {
298	      return;
299	    }
300	    final generation = _generation;
301	    emit(current.copyWith(isLoadingMore: true, loadMoreFailed: false));
302	    // spec-5-2 I/O matrix: "Load more with filters active" — the
303	    // continuation carries the exact same filter selection as whichever
304	    // `_loadFiltered()` call fetched this page's own first page.
305	    final result = await _repository.list(
306	      cursor: current.nextCursor,
307	      source: _activeSource,
308	      dateFrom: _activeDateFrom,
309	      dateTo: _activeDateTo,
310	    );
311	    if (isClosed || generation != _generation) {
312	      return;
313	    }
314	    // Re-reads `state` rather than closing over `current` — defensive
315	    // against `loadFirstPage()` having reset the state to something other
316	    // than `MeusRegistrosLoaded` while this await was pending.
317	    final latest = state;
318	    if (latest is! MeusRegistrosLoaded) {
319	      return;
320	    }
321	    result.match(
322	      (failure) =>
323	          emit(latest.copyWith(isLoadingMore: false, loadMoreFailed: true)),
324	      (page) {
325	        // I/O matrix: "Next page appended, no dup ids" — defensive
326	        // de-duplication in case a cursor-boundary entry is ever repeated
327	        // by the server, including a repeat *within* this same page
328	        // (`dedupedById`'s running `seenIds` set covers both).
329	        final seenIds = latest.entries.map((entry) => entry.id).toSet();
330	        final newEntries = dedupedById(
331	          page.items,
332	          (entry) => entry.id,
333	          seenIds: seenIds,
334	        );
335	        // Defensive guard against a degenerate server response: if every
336	        // item in this "successful" page was already present by id (zero
337	        // genuinely-new entries) yet the server still reports a non-null
338	        // `nextCursor`, treat the page as exhausted rather than trusting
339	        // that cursor — otherwise a misbehaving/stuck server cursor could
340	        // make the scroll listener keep re-triggering `loadMore()`
341	        // indefinitely with no progress.
342	        final nextCursor = newEntries.isEmpty ? null : page.nextCursor;
343	        emit(
344	          MeusRegistrosLoaded(
345	            entries: [...latest.entries, ...newEntries],
346	            nextCursor: nextCursor,
347	            pendingWrites: latest.pendingWrites,
348	          ),
349	        );
350	      },
351	    );
352	  }
353	
354	  @override
355	  Future<void> close() async {
356	    await _pendingSubscription.cancel();
357	    await _confirmedSubscription.cancel();
358	    return super.close();
359	  }
